package com.graduation.homework.domain;import com.graduation.homework.auth.AuthService;import com.graduation.homework.common.ApiException;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/submissions")public class SubmissionController{private final SubmissionRepository repo;private final AssignmentRepository assignments;private final AuthService auth;public SubmissionController(SubmissionRepository r,AssignmentRepository a,AuthService au){repo=r;assignments=a;auth=au;}public record Submit(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long assignmentId,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=10000) String content,@jakarta.validation.constraints.Size(max=2000) String attachmentUrl){}public record Grade(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.DecimalMin("0.0") BigDecimal score,@jakarta.validation.constraints.Size(max=3000) String feedback){}@PostMapping public Submission submit(@jakarta.validation.Valid @RequestBody Submit x){var u=auth.currentUser();var a=assignments.findById(x.assignmentId()).orElseThrow(()->ApiException.notFound("作业不存在"));if(LocalDateTime.now().isAfter(a.getDueAt()))throw ApiException.badRequest("作业已截止");var s=repo.findByAssignmentIdAndUserId(a.getId(),u.getId()).orElseGet(Submission::new);s.setAssignmentId(a.getId());s.setUserId(u.getId());s.setContent(x.content());s.setAttachmentUrl(x.attachmentUrl());s.setSubmittedAt(LocalDateTime.now());s.setStatus("SUBMITTED");return repo.save(s);}@GetMapping public List<Submission> list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}@PatchMapping("/{id}/grade")@PreAuthorize("hasRole('ADMIN')")public Submission grade(@PathVariable Long id,@jakarta.validation.Valid @RequestBody Grade g){var s=repo.findById(id).orElseThrow(()->ApiException.notFound("提交不存在"));var a=assignments.findById(s.getAssignmentId()).orElseThrow();if(g.score()==null||g.score().compareTo(BigDecimal.ZERO)<0||g.score().compareTo(a.getMaxScore())>0)throw ApiException.badRequest("分数超出范围");s.setScore(g.score());s.setFeedback(g.feedback());s.setStatus("GRADED");return repo.save(s);}}
